function policyInline(host, text) {
  // The frozen policy is trusted data, but never insert Markdown as HTML.
  const parts=String(text).split(/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g);
  for(const part of parts){if(part.startsWith("`")&&part.endsWith("`"))host.append(node("code",part.slice(1,-1)));else if(part.startsWith("**")&&part.endsWith("**"))host.append(node("strong",part.slice(2,-2)));else if(/^\[[^\]]+\]\([^)]+\)$/.test(part))host.append(document.createTextNode(part.slice(1,part.indexOf("]("))));else host.append(document.createTextNode(part));}
  return host;
}
function policyDocument(host, text) {
  host.replaceChildren();const lines=String(text).split(/\r?\n/);let index=0;
  const isTable=line=>/^\s*\|.*\|\s*$/.test(line);
  while(index<lines.length){const line=lines[index];if(!line.trim()){index++;continue;}
    if(/^```/.test(line)){const code=[];index++;while(index<lines.length&&!/^```/.test(lines[index]))code.push(lines[index++]);host.append(node("pre",code.join("\n")));index++;continue;}
    const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){host.append(policyInline(node("h"+Math.min(heading[1].length+1,4)),heading[2]));index++;continue;}
    if(isTable(line)&&/^\s*\|[\s:|\-]+\|\s*$/.test(lines[index+1]||"")){const table=node("table",undefined,"comparison-table");let rowIndex=0;while(index<lines.length&&isTable(lines[index])){const value=lines[index++];if(rowIndex===1){rowIndex++;continue;}const row=node("tr");for(const cell of value.trim().slice(1,-1).split("|"))row.append(policyInline(node(rowIndex===0?"th":"td"),cell.trim()));table.append(row);rowIndex++;}host.append(table);continue;}
    if(/^\s*(?:[-*]|\d+\.)\s+/.test(line)){const ordered=/^\s*\d+\./.test(line),list=node(ordered?"ol":"ul");while(index<lines.length&&/^\s*(?:[-*]|\d+\.)\s+/.test(lines[index]))list.append(policyInline(node("li"),lines[index++].replace(/^\s*(?:[-*]|\d+\.)\s+/,"")));host.append(list);continue;}
    if(/^>\s?/.test(line)){host.append(policyInline(node("blockquote"),line.replace(/^>\s?/,"")));index++;continue;}
    const paragraph=[line];index++;while(index<lines.length&&lines[index].trim()&&!/^(?:#{1,6}\s|```|>\s?|\s*[-*]\s|\s*\d+\.\s)/.test(lines[index])&&!isTable(lines[index]))paragraph.push(lines[index++]);host.append(policyInline(node("p"),paragraph.join("\n")));
  }
}
