function renderTrajectories(host,value) {
  const rows=[];
  if(Array.isArray(value)) rows.push(...value);
  else for(const [outer,data] of Object.entries(value)) {
    if(!data || typeof data!=="object")continue;
    if(data.hate || data.group) {
      for(const task of ["hate","group"]) if(data[task])rows.push({condition:outer,task,...data[task]});
    } else if(Array.isArray(data))rows.push(...data.map(row=>({task:outer,...row})));
    else for(const [condition,row] of Object.entries(data.conditions||data))
      if(row&&typeof row==="object")rows.push({task:outer,condition,...row});
  }
  const usable=rows.filter(row=>row.prediction!==undefined||row.predicted!==undefined||row.predicted_label!==undefined||row.selected!==undefined);
  if(!usable.length){host.append(node("pre",JSON.stringify(value,null,2),"json-detail"));return;}
  const table=node("table",undefined,"comparison-table");const head=node("tr");
  ["任务 / 条件","预测"].forEach(text=>head.append(node("th",text)));table.append(head);
  for(const row of usable){const tr=node("tr");tr.append(node("td",`${row.task || ""} ${row.condition || row.name || ""}`),node("td",humanLabel(row.prediction??row.predicted??row.predicted_label??row.selected)));table.append(tr);}
  host.append(table);
}

