function validation(action){if(draft._group_mode==="classes"&&!draft.group?.length){errorMessage("请选择至少一个类别，或改选无类别 / 未决。");return false;}if(!action.startsWith("confirm"))return true;if(reasonNeedsCheck){errorMessage("请先核对修改后的依据。");return false;}if((draft.hate_reason==="other"||draft.group_reason==="other"||(draft.expression_types||[]).includes("other"))&&!String(draft.note||"").trim()){errorMessage("选择其他原因时，请补一句现有选项无法表达的内容。");return false;}return true;}
