async function flush(){if(conflict){errorMessage("请先恢复或下载当前草稿，再切换。","为防止丢失修改，当前仍停留在这一项。");return false;}return !dirty||await mutate(mode==="comparison"?"save_assessment":"save_object");}
async function loadCase(itemId,{recover=true,preserveObject=null}={}){const data=await get("/api/evidence/items/"+encodeURIComponent(itemId));const token=bootstrap.session_token;bootstrap={...(data.bootstrap||bootstrap),session_token:data.bootstrap?.session_token||token};if(data.revision!==undefined)bootstrap.revision=data.revision;current=data.current||data;openedObjects=new Set();exposure=clone(current.review.prior_exposure);object=current.objects.find(o=>o.id===preserveObject)||current.objects.find(o=>o.review?.status!=="confirmed"||isStale(o))||current.objects[0];mode=current.comparison&&!current.stale?"comparison":"materials";kind="all";dirty=false;reasonNeedsCheck=false;recoveryNeedsSave=false;draft=mode==="comparison"?assessmentFor():valuesFor(object);show($("resume-notice"),false);if(recover){let local;try{local=JSON.parse(localStorage.getItem(key(itemId))||"null");}catch(_){}if(local){conflict=local;errorMessage("找到尚未保存的本地草稿。","当前展示服务器记录；可以下载草稿，或载入最新状态并明确恢复。");}}try{localStorage.setItem(key("position"),itemId);}catch(_){}renderCurrent();setState("saved","已载入保存记录");}
async function navigate(itemId){if(!itemId||current?.item_id===itemId||busy||materialNavigating||!await flush())return;busy=true;syncControls();try{await loadCase(itemId);closeSidebar();$("source-pane").scrollTop=0;$("decision-pane").scrollTop=0;if(innerWidth<=760)window.scrollTo({top:0,behavior:"instant"});}catch(error){errorMessage("案例读取失败，当前草稿仍保留。",error.message);}finally{busy=false;syncControls();}}
async function selectObject(id,{selectedKind}={}){
  if(!current||busy||materialNavigating){$("object-select").value=object?.id||"";return false;}
  if(!current.objects.some(row=>row.id===id))return false;
  // Acquire a navigation lock before awaiting the save. Repeated clicks cannot
  // start a second save or apply a different target while the first is pending.
  materialNavigating=true;syncControls();
  try{
    if(!await flush())return false;
    const next=current.objects.find(row=>row.id===id);if(!next)return false;
    if(selectedKind!==undefined)kind=selectedKind;
    object=next;mode="materials";draft=valuesFor(object);dirty=false;reasonNeedsCheck=false;pendingSelection=null;
    renderCurrent();setState("saved",isLocked()?"已载入确认记录":groupOnlyRecheck()?"已载入既有确认 · group 待重核":object.review?.version>0?"已载入保存记录":"AI 初稿 · 待核对");return true;
  }finally{materialNavigating=false;$("object-select").value=object?.id||"";syncControls();}
}
async function moveObject(direction){
  if(mode!=="materials"||busy||materialNavigating||conflict||!current)return false;
  const rows=filteredObjects(), index=rows.findIndex(row=>row.id===object?.id), next=rows[index+direction];
  if(index<0||!next)return false;
  return selectObject(next.id);
}
async function setMode(next){if(next===mode||busy||materialNavigating||next==="comparison"&&!current.comparison||!await flush())return;mode=next;draft=next==="comparison"?assessmentFor():valuesFor(object);reasonNeedsCheck=false;renderCurrent();}
async function primary(){if(mode==="comparison"){const before=[...visibleIds];if(await mutate("confirm")){const start=before.indexOf(current.item_id);const ordered=before.slice(start+1).concat(before.slice(0,start));const next=ordered.find(id=>bootstrap.items.find(i=>i.item_id===id)?.status!=="confirmed");if(next)await navigate(next);}}else{if(await mutate("confirm_object")){const start=current.objects.findIndex(o=>o.id===object.id);const next=current.objects.slice(start+1).concat(current.objects.slice(0,start)).find(o=>o.review?.status!=="confirmed"||isStale(o));if(next){kind="all";await selectObject(next.id);}else{$("reveal-comparison").focus();}}}}
async function recoverLocal(){if(busy||!conflict)return;const local=clone(conflict);busy=true;syncControls();try{await loadCase(local.item_id,{recover:false,preserveObject:local.object_id});mode=local.mode;object=current.objects.find(o=>o.id===local.object_id)||object;if(mode==="comparison"&&!current.comparison){conflict=local;errorMessage("材料状态已改变，原本地裁决草稿仍保留。","先下载草稿并核对最新材料。");return;}if(isLocked()||groupOnlyRecheck()&&changesProtectedFields(local.values)){conflict=local;draft=mode==="comparison"?assessmentFor():valuesFor(object);renderCurrent();errorMessage(groupOnlyRecheck()?"本地草稿包含本次 group 重核之外的修改。":"服务器上的这项记录已确认。","草稿仍保留；需要合并时先重新打开记录，再恢复草稿。");return;}conflict=null;draft=clone(local.values);exposure=mergedExposure(local.prior_exposure);dirty=true;recoveryNeedsSave=true;reasonNeedsCheck=false;clearError();backup();renderCurrent();$("resume-notice").textContent="已在最新版本上恢复本地草稿。请核对后手动保存；不会自动覆盖服务器。";show($("resume-notice"),true);setState("dirty","已恢复草稿 · 请手动保存");}catch(error){conflict=local;errorMessage("无法读取最新状态，本地草稿仍保留。",error.message);}finally{busy=false;syncControls();}}
const FIELD_LABELS={hate:"仇恨判断",group:"群体判断",hate_reason:"hate 依据",group_reason:"group 依据",stance:"立场",target_types:"对象",expression_types:"表达类型",hate_original_status:"原 hate 标注",group_original_status:"原 group 标注",topic_hate:"hate 词义关联",rule_hate:"hate 规则关联",topic_group:"group 词义关联",rule_group:"group 规则关联",lexicon_risk:"带入不适配词典",definition_verdict:"定义自身",source_fit:"来源位置适配",query_fit:"当前查询适配",issues:"问题标记",evidence:"原文依据",note:"补充备注"};
async function openBatch(){
  if(busy||!await flush())return;
  batchRows=current.objects.filter(o=>openedObjects.has(o.id)&&(o.review.status!=="confirmed"||isStale(o))).map(o=>({object_id:o.id,object_version:o.review.version,values:valuesFor(o),source_version:o.version,ai_version:o.ai_draft.version}));
  const host=$("batch-items");host.replaceChildren();show($("batch-error"),false);
  for(const row of batchRows){
    const o=current.objects.find(value=>value.id===row.object_id);const article=node("article",undefined,"batch-item");article.dataset.objectId=o.id;article.append(node("h3",objectTitle(o)),node("p",`审核版本 v${row.object_version} · AI ${row.ai_version}`,"object-meta"));if(groupRecheck(o))article.append(node("p",o.review?.group_only_recheck?"本项仅确认 group 已按 v2 重核；既有 hate 和共同依据保持原确认。":"AI 初稿没有按 v2 更新；请按当前规则核对 group。", "stale-warning"));
    for(const block of sourceBlocks(o)){article.append(node("strong",block.title),node("p",block.text,"source-text"));}
    if(o.source.original_answer)article.append(node("p",`示例原答案：hate ${humanLabel(o.source.original_answer.hate)} · group ${humanLabel(o.source.original_answer.group)}`,"source-verification"));
    const list=node("dl",undefined,"batch-values");
    for(const [field,value]of Object.entries(row.values)){let text;if(field==="evidence")text=value.length?value.map(span=>`${sourceLabel(span.source)}：「${span.text}」`).join("\n"):"无高亮片段";else if(field==="group"||field==="hate")text=humanLabel(value);else if(Array.isArray(value))text=value.length?value.map(label).join("、"):"无";else text=value===null?"未决":value===""?"未填":label(value);list.append(node("dt",FIELD_LABELS[field]||field),node("dd",text));}article.append(list);
    const check=node("label",undefined,"batch-check");const input=node("input");input.type="checkbox";input.value=o.id;input.onchange=()=>{const count=host.querySelectorAll("input:checked").length;$("confirm-batch").disabled=!count;$("confirm-batch").textContent=`采纳所选 ${count} 项`;};check.append(input,node("span",o.review?.group_only_recheck?"我已按 group v2 核对上方全文、原答案（如有）及 group 字段，确认 group 重核。":"我已核对上方全文、原答案（如有）及全部裁决字段，确认此项。"));article.append(check);host.append(article);
  }
  if(!batchRows.length)host.append(node("p","当前没有已打开且待确认的材料。先在材料选择器中打开并核对。","empty-material"));
  $("confirm-batch").disabled=true;$("confirm-batch").textContent="采纳所选 0 项";$("batch-dialog").showModal();
}
async function confirmBatch(){
  const ids=new Set([...$("batch-items").querySelectorAll("input:checked")].map(input=>input.value));
  const selected=batchRows.filter(row=>ids.has(row.object_id));if(!selected.length||busy)return;
  // Topological order permits explicitly selected query/demo/definition dependencies.
  const remaining=[...selected], ordered=[], accepted=new Set(current.objects.filter(o=>o.review.status==="confirmed"&&!isStale(o)).map(o=>o.id));
  while(remaining.length){const index=remaining.findIndex(row=>current.objects.find(o=>o.id===row.object_id).depends_on.every(id=>accepted.has(id)));if(index<0){$("batch-error").textContent="所选关系还引用未确认材料，请返回先核对依赖，或将已核对的依赖明确纳入本次勾选。";show($("batch-error"),true);return;}const [row]=remaining.splice(index,1);ordered.push(row);accepted.add(row.object_id);}
  $("confirm-batch").disabled=true;
  if(await mutate("confirm_batch",{objects:ordered.map(({object_id,object_version,values})=>({object_id,object_version,values}))}))$("batch-dialog").close();
  else{$("batch-error").textContent=$("request-error-details").textContent||$("request-error-message").textContent;show($("batch-error"),true);$("confirm-batch").disabled=false;}
}
function closeSidebar(){$("item-sidebar").classList.remove("open");show($("sidebar-backdrop"),false);}
async function exportRecords(format){if(busy||!await flush())return;try{const response=await request("/api/evidence/export",{expected_revision:bootstrap.revision,format});download(await response.blob(),"evidence-human-adjudication."+format,format==="csv"?"text/csv":"application/json");}catch(error){errorMessage("导出失败",error.message);}}
function handleShortcut(event){
  if(event.defaultPrevented||event.isComposing||event.keyCode===229||document.querySelector("dialog[open]"))return;
  if((event.ctrlKey||event.metaKey)&&!event.altKey&&event.key.toLowerCase()==="s"){
    event.preventDefault();if(!event.repeat&&!isLocked()&&!materialNavigating)mutate(mode==="comparison"?"save_assessment":"save_object");return;
  }
  if(ECommon.isTextEntry(event.target)||event.repeat)return;
  if(event.altKey&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&(event.key==="ArrowUp"||event.key==="ArrowDown")){
    if(mode!=="materials"||!current)return;
    event.preventDefault();moveObject(event.key==="ArrowUp"?-1:1);return;
  }
  if(event.altKey||event.ctrlKey||event.metaKey||event.shiftKey)return;
  if(event.key==="[")$("previous-item").click();
  if(event.key==="]")$("next-item").click();
  if(event.key==="Escape")closeSidebar();
}
function bind(){ $("open-batch").onclick=openBatch;$("close-batch").onclick=$("dismiss-batch").onclick=()=>$("batch-dialog").close();$("confirm-batch").onclick=confirmBatch;$("item-search").oninput=renderQueue;$("item-filters").querySelectorAll("button").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$("item-filters").querySelectorAll("button").forEach(x=>x.classList.toggle("active",x===b));renderQueue();});$("object-kinds").querySelectorAll("button").forEach(b=>b.onclick=()=>{if(busy||materialNavigating||mode!=="materials")return;const rows=objectsOfKind(b.dataset.kind);if(rows.length)selectObject((rows.find(row=>row.id===object.id)||rows[0]).id,{selectedKind:b.dataset.kind});});$("previous-object").onclick=()=>moveObject(-1);$("next-object").onclick=()=>moveObject(1);$("object-select").onchange=()=>selectObject($("object-select").value);$("previous-item").onclick=()=>navigate(visibleIds[visibleIds.indexOf(current.item_id)-1]);$("next-item").onclick=()=>navigate(visibleIds[visibleIds.indexOf(current.item_id)+1]);$("save-draft").onclick=()=>mutate(mode==="comparison"?"save_assessment":"save_object");$("primary-action").onclick=primary;$("reveal-comparison").onclick=async()=>{if(await flush())await mutate("reveal");};$("tab-materials").onclick=()=>setMode("materials");$("tab-comparison").onclick=()=>setMode("comparison");$("recover-local").onclick=recoverLocal;$("download-draft").onclick=()=>download(draftBackup(),"evidence-local-draft-"+current.item_id+".json");$("sidebar-toggle").onclick=()=>{$("item-sidebar").classList.add("open");show($("sidebar-backdrop"),true);};$("sidebar-close").onclick=closeSidebar;$("sidebar-backdrop").onclick=closeSidebar;$("guidelines").onclick=()=>$("guideline-dialog").showModal();$("close-guidelines").onclick=$("dismiss-guidelines").onclick=()=>$("guideline-dialog").close();$("mobile-materials").onclick=()=>$("object-material").scrollIntoView({block:"start",behavior:"smooth"});$("mobile-decision").onclick=()=>$("decision-pane").scrollIntoView({block:"start",behavior:"smooth"});$("export-json").onclick=()=>exportRecords("json");$("export-csv").onclick=()=>exportRecords("csv");$("reopen").onclick=async()=>{if(busy||!conflict&&!await flush())return;$("reopen-note").value="";$("reopen-dialog").showModal();};$("cancel-reopen").onclick=()=>$("reopen-dialog").close();$("reopen-reason").onchange=()=>show($("reopen-note-field"),$("reopen-reason").value==="other");$("confirm-reopen").onclick=async()=>{const code=$("reopen-reason").value;const reason=code==="other"?$("reopen-note").value.trim():label(code);if(!reason){$("reopen-note").focus();return;}if(await mutate(mode==="comparison"?"reopen":"reopen_object",{reason}))$("reopen-dialog").close();};$("review-form").onsubmit=e=>e.preventDefault();document.addEventListener("keydown",handleShortcut);window.addEventListener("beforeunload",event=>{if(dirty||busy||conflict){backup();event.preventDefault();event.returnValue="";}});}
async function start(){bind();try{bootstrap=await get("/api/evidence/bootstrap");let previous;try{previous=localStorage.getItem(key("position"));}catch(_){}const first=bootstrap.items.find(row=>row.item_id===previous)||bootstrap.items.find(row=>row.status!=="confirmed")||bootstrap.items[0];if(!first){errorMessage("当前没有授权审核案例。");return;}await loadCase(first.item_id);}catch(error){errorMessage("无法连接证据审核工作台。",error.message);setState("error");}}
start();

function renderFinalAnnotation(host) {
  const final=object?.review?.final_annotation;
  if(!final)return;
  const active=final.approved_version===object.review.version && object.review.status==="confirmed";
  const section=node("section",undefined,"value-section");
  section.dataset.finalAnnotation="true";
  section.append(node("h3",active?"本轮最终采纳结果":"此前批量采纳记录"));
  if(Object.hasOwn(final.values,"attack_severity"))section.append(node("p",`攻击严重度：${final.values.attack_severity} / 4`));
  if(final.adopted_definition)section.append(node("p",`采纳释义：${final.adopted_definition}`));
  section.append(node("p","由复核人明确批量采纳；原逐字段 AI 与人工来源保留。","field-help"));
  if(final.unreviewed_supporting_fields?.includes("hate_original_status"))section.append(node("p","本轮确认句子标签，未新增对原标注对错的裁决。","field-help"));
  const details=node("details",undefined,"secondary-detail");
  details.append(node("summary","字段来源、适用规则与采纳记录"),node("pre",JSON.stringify(final,null,2),"json-detail"));
  section.append(details);host.append(section);
}
